def investigate(context, acquire):
    receipts = acquire("history")
    actions = context.get("actions", [])
    goal = context.get("goal")

    def run(acts, pm, cm, tr):
        main = {}
        other = {}
        committed = {}
        main_changes = 0
        main_total = 0
        other_total = 0
        in_tx = None
        tx_snapshot = None
        for act in acts:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'put':
                store = main if conn == 'main' else other
                existed = act.get('key') in store
                if pm == 'ignore':
                    if existed:
                        changed = 0
                    else:
                        store[act.get('key')] = act.get('value')
                        changed = 1
                else:
                    store[act.get('key')] = act.get('value')
                    changed = 1
                if conn == 'main':
                    main_changes = changed
                    main_total += changed
                else:
                    other_total += changed
            elif op == 'update':
                store = main if conn == 'main' else other
                if act.get('key') in store:
                    store[act.get('key')] = act.get('value')
                    changed = 1
                else:
                    changed = 0
                if conn == 'main':
                    main_changes = changed
                    main_total += changed
                else:
                    other_total += changed
            elif op == 'delete':
                store = main if conn == 'main' else other
                if act.get('key') in store:
                    del store[act.get('key')]
                    changed = 1
                else:
                    changed = 0
                if conn == 'main':
                    main_changes = changed
                    main_total += changed
                else:
                    other_total += changed
            elif op == 'begin':
                in_tx = conn
                tx_snapshot = dict(main) if conn == 'main' else dict(other)
            elif op == 'commit':
                if in_tx == 'main':
                    committed = dict(main)
                else:
                    committed = dict(other)
                in_tx = None
            elif op == 'rollback':
                if in_tx == 'main':
                    main = tx_snapshot
                else:
                    other = tx_snapshot
                in_tx = None
        if in_tx is None:
            committed = dict(main)
        if cm == 'changes':
            ch = main_changes
        elif cm == 'total_main':
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(committed), sum(committed.values())

    modes = ['ignore', 'replace', 'upsert']
    channels = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    candidates = []
    for pm in modes:
        for cm in channels:
            for tr in triggers:
                ok = True
                for r in receipts:
                    ra = r.get('actions', [])
                    obs = r.get('observed', {})
                    ch, cc, cs = run(ra, pm, cm, tr)
                    if ch != obs.get('channel') or cc != obs.get('committed_count') or cs != obs.get('committed_sum'):
                        ok = False
                        break
                if ok:
                    candidates.append((pm, cm, tr))

    if not candidates:
        return {"value": None, "unresolved": True}

    results = set()
    for pm, cm, tr in candidates:
        ch, cc, cs = run(actions, pm, cm, tr)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cc)
        elif goal == 'committed_sum':
            results.add(cs)

    if len(results) == 1:
        return {"value": list(results)[0], "unresolved": False}
    return {"value": None, "unresolved": True}

def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        table = {}
        committed = {}
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0
        in_tx = False
        tx_conn = None
        tx_snapshot = None

        def do_write(conn, op, key, value):
            nonlocal main_changes, other_changes, main_total, other_total
            changed = 0
            if op == "put":
                if key in table:
                    if put_mode == "ignore":
                        changed = 0
                    else:
                        table[key] = value
                        changed = 1
                else:
                    table[key] = value
                    changed = 1
            elif op == "update":
                if key in table:
                    table[key] = value
                    changed = 1
            elif op == "delete":
                if key in table:
                    del table[key]
                    changed = 1
            if conn == "main":
                main_changes = changed
                main_total += changed
            else:
                other_changes = changed
                other_total += changed

        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            key = action.get("key")
            value = action.get("value")
            if op == "begin":
                if not in_tx:
                    in_tx = True
                    tx_conn = conn
                    tx_snapshot = (dict(table), dict(committed), main_changes, other_changes, main_total, other_total)
            elif op == "commit":
                if in_tx:
                    committed = dict(table)
                    in_tx = False
                    tx_conn = None
                    tx_snapshot = None
            elif op == "rollback":
                if in_tx:
                    table, committed, main_changes, other_changes, main_total, other_total = tx_snapshot
                    in_tx = False
                    tx_conn = None
                    tx_snapshot = None
            else:
                do_write(conn, op, key, value)

        if channel_mode == "changes":
            channel = main_changes
        elif channel_mode == "total":
            channel = main_total
        else:
            channel = main_total + other_total
        return channel, len(committed), sum(committed.values())

    def consistent(put_mode, trigger, channel_mode):
        for receipt in history:
            actions = receipt.get("actions", [])
            observed = receipt.get("observed", {})
            ch, cc, cs = simulate(actions, put_mode, trigger, channel_mode)
            if ch != observed.get("channel"):
                return False
            if cc != observed.get("committed_count"):
                return False
            if cs != observed.get("committed_sum"):
                return False
        return True

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for trigger in (False, True):
            for channel_mode in ("changes", "total", "both"):
                if consistent(put_mode, trigger, channel_mode):
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    values = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cc, cs = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            values.append(ch)
        elif goal == "committed_count":
            values.append(cc)
        elif goal == "committed_sum":
            values.append(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(set(values)) == 1:
        return {"value": values[0], "unresolved": False}
    return {"value": None, "unresolved": True}

def investigate(context, acquire):
    history = acquire("history")

    def simulate(actions, put_op, channel_type, trigger):
        committed = {}
        main_tx = None
        other_tx = None
        total_changes_main = 0
        total_changes_other = 0
        last_changes_main = 0

        def get_effective(conn):
            if conn == 'main':
                tx = main_tx
            else:
                tx = other_tx
            if tx is None:
                return dict(committed)
            eff = dict(committed)
            for k, v in tx.items():
                if v is None:
                    if k in eff:
                        del eff[k]
                else:
                    eff[k] = v
            return eff

        def apply_put(conn, key, value):
            nonlocal committed, main_tx, other_tx, total_changes_main, total_changes_other, last_changes_main
            eff = get_effective(conn)
            exists = key in eff
            changes = 0
            if put_op == 'ignore':
                if not exists:
                    changes = 1
                    if conn == 'main':
                        if main_tx is not None:
                            main_tx[key] = value
                        else:
                            committed[key] = value
                    else:
                        if other_tx is not None:
                            other_tx[key] = value
                        else:
                            committed[key] = value
            elif put_op == 'replace':
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = value
                    else:
                        committed[key] = value
                else:
                    if other_tx is not None:
                        other_tx[key] = value
                    else:
                        committed[key] = value
            elif put_op == 'upsert':
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = value
                    else:
                        committed[key] = value
                else:
                    if other_tx is not None:
                        other_tx[key] = value
                    else:
                        committed[key] = value
            if conn == 'main':
                total_changes_main += changes
                last_changes_main = changes
            else:
                total_changes_other += changes
            if trigger and changes > 0:
                if conn == 'main':
                    total_changes_main += 1
                else:
                    total_changes_other += 1

        def apply_update(conn, key, value):
            nonlocal committed, main_tx, other_tx, total_changes_main, total_changes_other, last_changes_main
            eff = get_effective(conn)
            if key in eff:
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = value
                    else:
                        committed[key] = value
                else:
                    if other_tx is not None:
                        other_tx[key] = value
                    else:
                        committed[key] = value
            else:
                changes = 0
            if conn == 'main':
                total_changes_main += changes
                last_changes_main = changes
            else:
                total_changes_other += changes

        def apply_delete(conn, key):
            nonlocal committed, main_tx, other_tx, total_changes_main, total_changes_other, last_changes_main
            eff = get_effective(conn)
            if key in eff:
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = None
                    else:
                        if key in committed:
                            del committed[key]
                else:
                    if other_tx is not None:
                        other_tx[key] = None
                    else:
                        if key in committed:
                            del committed[key]
            else:
                changes = 0
            if conn == 'main':
                total_changes_main += changes
                last_changes_main = changes
            else:
                total_changes_other += changes

        for action in actions:
            op = action.get('op')
            conn = action.get('connection', 'main')
            if op == 'put':
                apply_put(conn, action['key'], action['value'])
            elif op == 'update':
                apply_update(conn, action['key'], action['value'])
            elif op == 'delete':
                apply_delete(conn, action['key'])
            elif op == 'begin':
                if conn == 'main':
                    main_tx = {}
                else:
                    other_tx = {}
            elif op == 'commit':
                if conn == 'main':
                    if main_tx is not None:
                        for k, v in main_tx.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        main_tx = None
                else:
                    if other_tx is not None:
                        for k, v in other_tx.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        other_tx = None
            elif op == 'rollback':
                if conn == 'main':
                    main_tx = None
                else:
                    other_tx = None

        if channel_type == 'changes':
            channel = last_changes_main
        elif channel_type == 'total_main':
            channel = total_changes_main
        else:
            channel = total_changes_main + total_changes_other

        committed_count = len(committed)
        committed_sum = sum(committed.values())
        return channel, committed_count, committed_sum

    put_ops = ['ignore', 'replace', 'upsert']
    channel_types = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    consistent = []
    for put_op in put_ops:
        for channel_type in channel_types:
            for trigger in triggers:
                ok = True
                for receipt in history:
                    actions = receipt['actions']
                    observed = receipt['observed']
                    ch, cc, cs = simulate(actions, put_op, channel_type, trigger)
                    if ch != observed['channel'] or cc != observed['committed_count'] or cs != observed['committed_sum']:
                        ok = False
                        break
                if ok:
                    consistent.append((put_op, channel_type, trigger))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context['goal']
    actions = context['actions']

    results = set()
    for put_op, channel_type, trigger in consistent:
        ch, cc, cs = simulate(actions, put_op, channel_type, trigger)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cc)
        elif goal == 'committed_sum':
            results.add(cs)

    if len(results) == 1:
        return {"value": list(results)[0], "unresolved": False}
    else:
        return {"value": None, "unresolved": True}
